import{_ as r,C as o,o as a,c as d,a2 as n,b as p,w as e,a as l,E as i,a3 as u}from"./chunks/framework.BC3NdntU.js";const B=JSON.parse('{"title":"11.11 工具与框架选型(LangGraph / CrewAI / 自建)","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.11-工具与框架选型.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.11-工具与框架选型.md","lastUpdated":1789011061000}'),h={name:"卷十一-AIAgentHarness与提示词工程/11.11-工具与框架选型.md"};function g(A,t,c,E,b,q){const s=o("Mermaid");return a(),d("div",null,[t[1]||(t[1]=n('<h1 id="_11-11-工具与框架选型-langgraph-crewai-自建" tabindex="-1">11.11 工具与框架选型(LangGraph / CrewAI / 自建) <a class="header-anchor" href="#_11-11-工具与框架选型-langgraph-crewai-自建" aria-label="Permalink to &quot;11.11 工具与框架选型(LangGraph / CrewAI / 自建)&quot;">​</a></h1><h2 id="引言-别盯着-star-数选框架" tabindex="-1">引言:别盯着 Star 数选框架 <a class="header-anchor" href="#引言-别盯着-star-数选框架" aria-label="Permalink to &quot;引言:别盯着 Star 数选框架&quot;">​</a></h2><p>2026 年 Multi-Agent 已成为 AI 落地标配,但&quot;生产就绪&quot;不等于&quot;适合你&quot;。同一个需求,选 LangGraph 写 200 行、CrewAI 写 30 行、自建写 50 行——差异巨大。这一章给 2026 年的选型判断。(呼应 11.3:框架是&quot;可选加速器&quot;,不是&quot;必须依赖&quot;。)</p><hr><h2 id="一、2026-年框架格局-已洗牌" tabindex="-1">一、2026 年框架格局(已洗牌) <a class="header-anchor" href="#一、2026-年框架格局-已洗牌" aria-label="Permalink to &quot;一、2026 年框架格局(已洗牌)&quot;">​</a></h2>',5)),(a(),p(u,null,{default:e(()=>[i(s,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BLangGraph%3Cbr%2F%3E%E5%9B%BE%E7%BC%96%E6%8E%92%C2%B7%E7%94%9F%E4%BA%A7%E4%B8%BB%E6%B5%81%2044%25%5D%20--%3E%20D%5B2026%20%E5%8F%8C%E9%9B%84%5D%0A%20%20%20%20B%5BCrewAI%3Cbr%2F%3E%E8%A7%92%E8%89%B2%E5%9B%A2%E9%98%9F%C2%B7%E5%BC%80%E7%AE%B1%E5%8D%B3%E7%94%A8%5D%20--%3E%20D%0A%20%20%20%20C%5BAutoGen%3Cbr%2F%3E2025%E5%BA%95%E5%B7%B2%E7%BB%B4%E6%8A%A4%E6%A8%A1%E5%BC%8F%E9%80%80%E5%9C%BA%5D%20--%3E%20E%5B%E8%A2%AB%20Microsoft%20Agent%20Framework%20%E6%8E%A5%E6%A3%92%5D%0A%20%20%20%20F%5BLlamaIndex%3Cbr%2F%3E%E5%81%8F%E6%95%B0%E6%8D%AE%2FRAG%E7%AE%A1%E9%81%93%5D%20--%3E%20G%5B%E6%95%B0%E6%8D%AE%E7%AE%A1%E9%81%93%E4%B8%93%E7%94%A8%5D%0A%20%20%20%20H%5B%E8%87%AA%E5%BB%BA%20%2F%20OpenAI%20SDK%20%2F%20Claude%20Code%20SDK%5D%20--%3E%20I%5B%E8%BD%BB%E9%87%8F%E5%9C%BA%E6%99%AF%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n(`<p><strong>谁退场了</strong>:AutoGen 在 2025 年底进入维护模式(不再接新功能),微软引导用户转向 Microsoft Agent Framework——它不是不行,而是&quot;对等对话协商&quot;在长任务可控性上不如专门做状态治理的框架。</p><hr><h2 id="二、主流方案对比" tabindex="-1">二、主流方案对比 <a class="header-anchor" href="#二、主流方案对比" aria-label="Permalink to &quot;二、主流方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>心智模型</th><th>强项</th><th>代价</th><th>适合</th></tr></thead><tbody><tr><td><strong>LangGraph</strong></td><td>有向图(节点+状态流转)</td><td>状态管理、checkpoint 回滚、人工审批、生产治理</td><td>学习曲线最陡</td><td>复杂流程、需治理的 Agent</td></tr><tr><td><strong>CrewAI</strong></td><td>角色团队(研究员/分析/写手)</td><td>开箱即用、代码少(30 行)</td><td>细粒度可控性弱</td><td>快速搭多角色协作</td></tr><tr><td><strong>LlamaIndex</strong></td><td>数据管道/RAG</td><td>检索、索引、数据接入强</td><td>不是通用 Agent 编排</td><td>知识库问答、RAG</td></tr><tr><td><strong>OpenAI/Claude Code SDK</strong></td><td>轻量 SDK</td><td>原生、可控、易上手</td><td>要自己搭循环/状态</td><td>简单 Agent、快速验证</td></tr><tr><td><strong>Dify 等平台</strong></td><td>低代码/可视化</td><td>拖拽搭流程、非程序员可用</td><td>定制受限</td><td>业务侧快速原型</td></tr><tr><td><strong>自建</strong></td><td>手写 run_agent 循环</td><td>零依赖、完全可控、可懂</td><td>造轮子、功能要靠自己</td><td>简单场景、追求可控</td></tr></tbody></table><hr><h2 id="三、选型决策树" tabindex="-1">三、选型决策树 <a class="header-anchor" href="#三、选型决策树" aria-label="Permalink to &quot;三、选型决策树&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求是什么?</span></span>
<span class="line"><span>├─ 复杂状态流转 + 回滚 + 人工审批 + 生产治理 → LangGraph</span></span>
<span class="line"><span>├─ 快速搭&quot;多角色团队&quot;协作、原型优先 → CrewAI</span></span>
<span class="line"><span>├─ 知识库问答 / RAG / 数据检索 → LlamaIndex(或 LangChain + 向量库)</span></span>
<span class="line"><span>├─ 简单单 Agent、要轻量可控 → 自建 loop / OpenAI/Claude Code SDK</span></span>
<span class="line"><span>├─ 业务侧低代码、非程序员 → Dify 等平台</span></span>
<span class="line"><span>└─ 拿不准 → 先自建最简 ReAct(11.2 的 10 行),跑通再决定要不要上框架</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="四、关键判断-呼应-11-3-的结论" tabindex="-1">四、关键判断(呼应 11.3 的结论) <a class="header-anchor" href="#四、关键判断-呼应-11-3-的结论" aria-label="Permalink to &quot;四、关键判断(呼应 11.3 的结论)&quot;">​</a></h2><blockquote><p><strong>先懂原理,再选框架。</strong> 前几章把&quot;循环/状态/工具/上下文/容错&quot;讲透后,你会发现:任何框架都是这些能力的封装。所以:</p></blockquote><ol><li><strong>简单场景别上重框架</strong>:一个 <code>while + LLM + 工具</code> 循环能解决的,上 LangGraph 反而更复杂</li><li><strong>框架的价值在&quot;状态/回滚/编排&quot;</strong>:当 Agent 需要 checkpooint 回滚、多分支、人工审批时,自建这些很痛苦,框架才有意义</li><li><strong>别追新</strong>:AutoGen 的退场是教训——选&quot;生态成熟、有真实生产案例&quot;的,而非&quot;最新最炫&quot;的</li></ol><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2026 格局:LangGraph(图编排,生产主流)/ CrewAI(角色团队,快速)/ AutoGen 退场 / LlamaIndex(RAG)</span></span>
<span class="line"><span>选型:复杂治理→LangGraph;快速协作→CrewAI;RAG→LlamaIndex;简单→自建/SDK;低代码→Dify</span></span>
<span class="line"><span>心法:先懂原理再选;简单别上重框架;选成熟生态别追新</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="六、面试-实践要点" tabindex="-1">六、面试/实践要点 <a class="header-anchor" href="#六、面试-实践要点" aria-label="Permalink to &quot;六、面试/实践要点&quot;">​</a></h2><p><strong>Q1:为什么 AutoGen 会&quot;退场&quot;?</strong></p><p>它强在&quot;对等对话协商&quot;(多个 Agent 互相聊),但长任务的<strong>可控性、状态持久化、生产治理</strong>不如专门做状态管理的框架。这是&quot;技术可行&quot;但&quot;生产不友好&quot;的典型案例——选型要看<strong>生产治理能力</strong>,不是看概念新颖。</p><p><strong>Q2:LangGraph 和 CrewAI 的本质区别?</strong></p><p>LangGraph 把 Agent 建模成<strong>有向图</strong>(节点=步骤,边=流转),强调状态管理、回滚、人工审批、生产治理; CrewAI 把 Agent 建模成<strong>角色团队</strong>(每个 Agent 有角色/目标),强调开箱即用、快速搭多角色协作。一个&quot;重但可控&quot;,一个&quot;轻但快&quot;。</p><p><strong>Q3:什么场景应该&quot;自建&quot;而不是用框架?</strong></p><p>需求简单(单个 ReAct 循环、少数工具)、团队要<strong>零依赖 + 完全可控 + 能完全理解行为</strong>时,自建 10~50 行更划算。上框架的时机是:需要多 Agent 编排、checkpoint 回滚、复杂状态流转、人工审批等&quot;工程化能力&quot;时。</p><hr><p>📎 参考:LangGraph/LangChain、CrewAI、LlamaIndex 官方文档,2026 年 Agent 框架横评(腾讯新闻/什么值得买)</p>`,24))])}const _=r(h,[["render",g]]);export{B as __pageData,_ as default};
